import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root group for this node
  const root = new Group();

  // ------------------------------
  // Text handling
  // ------------------------------
  const textItems = config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textObjects = [];
  for (const item of textItems) {
    const txt = item?.text ?? '';
    const opts = {
      fontSize: item?.typography?.fontSize ?? 31,
      color: item?.role === 'headline' ? config.visual?.colors?.ink ?? '#16161d' : config.visual?.colors?.paper ?? '#e8ecf2',
      align: 'left',
    };
    const txtObj = ctx.fontAtlas.createText(txt, opts);
    txtObj.position.set(0, 0, 0.01);
    root.add(txtObj);
    textObjects.push(txtObj);
  }

  // ------------------------------
  // Textured plane
  // ------------------------------
  const planeGeom = new PlaneGeometry(7, 6);
  const planeMat = new MeshBasicNodeMaterial();
  planeMat.color = new Color('#0b0b10'); // surface color as base

  const planeMesh = new Mesh(planeGeom, planeMat);
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // ------------------------------
  // Cinematic primitives (none expected)
  // ------------------------------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name]?.(root, prim.params);
      if (handler) {
        primitiveHandles.push(handler);
      }
    }
  }

  // ------------------------------
  // User data for cleanup & handlers
  // ------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose primitives
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') ph.cleanup();
    }

    // Dispose GSAP timelines if any (none in this node but safeguard)
    gsap.globalTimeline.clear();

    // Dispose material, texture, geometry
    if (planeMat) {
      if (planeMat.map && typeof planeMat.map.dispose === 'function') {
        planeMat.map.dispose();
      }
      if (typeof planeMat.dispose === 'function') planeMat.dispose();
    }
    if (planeGeom && typeof planeGeom.dispose === 'function') planeGeom.dispose();

    // Dispose any text objects' resources if they expose dispose
    for (const txtObj of textObjects) {
      if (txtObj && typeof txtObj.traverse === 'function') {
        txtObj.traverse((child) => {
          if (child && child.geometry && typeof child.geometry.dispose === 'function') {
            child.geometry.dispose();
          }
          if (child && child.material && typeof child.material.dispose === 'function') {
            child.material.dispose();
          }
        });
      }
    }
  };

  return root;
}
